/* Two shapes. A full-bleed split has no container, so the row is a direct child
   of the section and the copy carries the page gutter itself; a boxed card sits
   inside the container with a rule around it. */
[data-bz-section="media-band"] .bz-block { padding-block: 0 }
[data-bz-section="media-band"] .bz-block + .bz-block { padding-block-start: 22px }
[data-bz-section="media-band"] [data-bz-node="mb-body"] { padding-block-start: 22px }
[data-bz-section="media-band"] [data-bz-node="mb-cta"] { padding-block-start: 28px }
[data-bz-section="media-band"] [data-bz-node="mb-body"] p:last-child { margin-bottom: 0 }
[data-bz-section="media-band"] h2 { font-size: 38px; line-height: 1.15; margin: 0 }
[data-bz-section="media-band"] .bz-eyebrow { margin-bottom: 18px }
[data-bz-section="media-band"] [data-bz-node="mb-body"] p { font-size: 16px; line-height: 1.7; color: var(--body-text); margin: 0 0 16px }
[data-bz-section="media-band"] [data-bz-node="mb-body"] p:last-child { margin-bottom: 0 }
[data-bz-section="media-band"] [data-bz-node="mb-body"] .bz-text { max-width: 480px }
[data-bz-section="media-band"] .bz-btns { margin-block: 0; gap: 14px }
[data-bz-section="media-band"] .bz-btn--link { text-decoration: none }
[data-bz-section="media-band"] [data-bz-node="mb-media"] { display: flex; min-height: 400px }
[data-bz-section="media-band"] [data-bz-node="mb-img"] { padding-block: 0; width: 100% }
[data-bz-section="media-band"] [data-bz-node="mb-img"] .bz-figure { margin: 0; height: 100% }
[data-bz-section="media-band"] [data-bz-node="mb-img"] img { width: 100%; height: 100%; object-fit: cover; display: block }

/* Full-bleed split: the copy half is padded to the page grid. */
[data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] {
  padding: 60px 40px 60px max(var(--container-pad), calc((100vw - var(--container)) / 2 + var(--container-pad)));
}
[data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-media"] { min-height: 400px }

/* Boxed card: a rule around the whole band, the copy padded inside it. */
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] { border: 1px solid var(--line); background: var(--card) }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 56px }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-media"] { min-height: 400px }
[data-bz-section="media-band"] .bz-section { padding-block: 0 }

@media (max-width: 1100px) {
  [data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 48px var(--container-pad-tablet) }
  [data-bz-section="media-band"] [data-bz-node="mb-media"] { min-height: 320px }
}
@media (max-width: 640px) {
  [data-bz-section="media-band"] > .bz-section > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 44px var(--container-pad-mobile) }
  [data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { padding: 32px 24px }
  [data-bz-section="media-band"] [data-bz-node="mb-media"] { min-height: 220px }
  [data-bz-section="media-band"] h2 { font-size: 28px }
}
/* The boxed variant carries the section rhythm on its container; the bleed
   variant is edge to edge with none. */
[data-bz-section="media-band"] > .bz-section > .bz-container { padding-block: var(--space-10) }
/* The boxed card sets its heading a step down and its copy at 15px. */
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] .bz-eyebrow { margin-bottom: 16px }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] h2 { font-size: 30px; line-height: 1.2 }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] [data-bz-node="mb-h"] + .bz-block { padding-block-start: 16px }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] [data-bz-node="mb-body"] .bz-text { max-width: none }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] [data-bz-node="mb-body"] p { font-size: 15px; line-height: 1.6 }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-media"] { min-height: 340px }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] { border-left: 1px solid var(--line) }
[data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] .bz-btns { gap: 12px }
@media (max-width: 640px) {
  /* The boxed variant is a bordered card holding the picture flush to its edge
     and the copy inset 24px. Side by side that reads as a card. Stacked on a
     phone it reads as a mistake: the card's surface is the same colour as the
     band behind it on every placement, so nothing draws the card, and the copy
     simply appears indented 25px further than the picture above it and than
     every other band on the page. The card's chrome is dropped here, which is
     invisible, and both halves line up on the page's own gutter. */
  [data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] {
    border: 0;
    background: none;
  }
  [data-bz-section="media-band"] .bz-container > [data-bz-node="mb-row"] > [data-bz-node="mb-copy"] {
    padding: 28px 0 0;
    border-left: 0;
  }
}
